// The op names are checked against the Rust request enums: a renamed op fails the type check here.

import { call } from "../abi.ts";
import type {
  Candidate,
  CataloguePlugin,
  Choice,
  Compatibility,
  EngineLatency,
  EngineRequest,
  PluginNeed,
  WarningAnswer,
} from "../types/index.ts";

type Op = EngineRequest["op"];

const ask = <R>(op: Op, args?: object): R => call<R>({ op, args });

/** A short fingerprint of a text, the same on every side of a write: what a write sends as the base it was edited from. */
export const textHash = (text: string): string => ask("text.hash", { text });

/** The share of a project's plugins an engine's catalogue has, and which are missing. */
export const compatibility = (
  needs: ReadonlyArray<PluginNeed>,
  catalogue: ReadonlyArray<CataloguePlugin>,
): Compatibility => ask("engine.compat", { needs, catalogue });

/** A link's latency in ms and its band: the round trip plus twice the buffer period. */
export const engineLatency = (
  networkMs: number,
  bufferFrames: number,
  sampleRate: number,
): EngineLatency =>
  ask("engine.latency", { networkMs, bufferFrames, sampleRate });

/** What an engine warning's prose is about, and the missing thing it reports, if any. */
export const readWarning = (message: string): WarningAnswer =>
  ask("engine.warning", { message });

/** The engine to use from what the registry offered, as an index; null index when the user has to be asked. */
export const chooseEngineAt = (
  candidates: ReadonlyArray<Candidate>,
  remembered?: string | null,
): Choice => ask("engine.choose", { candidates, remembered });
